/*
 * font.h - fixed-width bitmap fonts (Spleen 6x12 for text, 8x16 for headings).
 * Glyph tables are generated by tools/bdf2c.py into font_data.c.
 */
#pragma once
#include <stdint.h>

typedef struct {
    uint8_t w, h;              /* cell size in pixels */
    const uint8_t *rows;       /* 128 glyphs x h rows, one byte per row, top bit = left pixel */
} ui_font;

extern const ui_font font_6x12;
extern const ui_font font_8x16;

/* UI glyphs stored below the printable range */
#define UI_GLYPH_DOWN  "\x01"   /* more text below */
#define UI_GLYPH_UP    "\x02"   /* more text above */
#define UI_GLYPH_RIGHT "\x03"   /* selection marker */
#define UI_GLYPH_DOT   "\x04"   /* bullet */
